const { withGradleProperties } = require("@expo/config-plugins");

// android/gradle.properties is generated by every prebuild, so Gradle tuning
// can only live in a config plugin. The Expo template values are sized for a
// default project; this one compiles three local Kotlin modules plus the Expo
// modules, runs R8, shrinks resources and hosts lint in the same daemon, and
// its release daemon has already died of metaspace in CI with the template's
// 512 MiB.
//
// Measured on this project (see docs/PERFORMANCE.md, "Build times"):
// the build cache turns a rebuild after `npm run android:prebuild` or a
// deleted android/app/build from minutes of Kotlin/R8/lint work into cache
// restores, and the configuration cache skips the configuration phase, whose
// Expo autolinking step runs Node tooling on every invocation.

const PROPERTIES = {
  // 2 GiB is the template default and not enough for R8 plus the Kotlin
  // compiler front-end on this dependency graph; 512 MiB metaspace is the
  // value CI's daemon log blamed when it ran out ("Daemon will be stopped at
  // the end of the build after running out of JVM Metaspace").
  "org.gradle.jvmargs": "-Xmx4g -XX:MaxMetaspaceSize=1g",
  // Task outputs (R8, lint analyses, Kotlin compiles) go to
  // ~/.gradle/caches/build-cache-1 and are restored instead of recomputed.
  // CI persists that directory through gradle/actions/setup-gradle; the
  // master warm-up job in .github/workflows/ci.yml fills it there.
  "org.gradle.caching": "true",
  // Repeat builds with unchanged build scripts skip the configuration phase
  // entirely. `problems=warn` is required: Gradle 9 fails the build on any
  // configuration-cache problem, and AGP and Kotlin still report deprecations
  // that are harmless here. If a problem ever invalidates the entry, Gradle
  // falls back to a normal configuration run rather than failing.
  "org.gradle.configuration-cache": "true",
  "org.gradle.configuration-cache.problems": "warn",
};

module.exports = function withGradlePerformance(config) {
  return withGradleProperties(config, (config) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const existing = config.modResults.find(
        (item) => item.type === "property" && item.key === key,
      );
      if (existing) {
        existing.value = value;
      } else {
        config.modResults.push({ type: "property", key, value });
      }
    }
    return config;
  });
};
